test('createInvoice accepts discountPercent on a line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice accepts decimal discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 12.5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

test('createInvoice defaults discountPercent to 0', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('createInvoice rejects negative discountPercent', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: -1 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice rejects discountPercent above 100', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 101 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice rejects non-numeric discountPercent', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 'ten' }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice rejects null discountPercent', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: null }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice accepts 0 and 100 as valid boundaries', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(r1.ok, true);
  assert.equal(r1.value.lines[0].discountPercent, 0);

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 100 }],
  });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[0].discountPercent, 100);
});

test('lineDiscount calculates discount from discountPercent', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 10 }), 1000);
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 50 }), 5000);
  assert.equal(lineDiscount({ qty: 1, unitPrice: 8500, discountPercent: 12.5 }), 1062.5);
});

test('lineDiscount defaults discountPercent to 0 if not provided', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000 }), 0);
});

test('lineDiscount clamps discount to 0 minimum', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: -1000, discountPercent: 10 }), 0);
});

test('invoiceTotals returns discount field', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.total, 9000);
});

test('invoiceTotals sums discounts across multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10 },
      { qty: 5, unitPrice: 2000, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000 + 10000);
  assert.equal(totals.discount, 1000 + 2000);
  assert.equal(totals.total, 20000 - 3000);
});

test('invoiceTotals handles mixed discount and no-discount lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10 },
      { qty: 5, unitPrice: 2000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000 + 10000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.total, 20000 - 1000);
});

test('invoiceTotals clamps total to 0 minimum', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 100 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.total, 0);
});

test('invoiceTotals clamps total when discount exceeds subtotal', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 50 },
      { qty: 5, unitPrice: 2000, discountPercent: 60 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 5000 + 6000);
  assert.equal(totals.total, 0);
});

test('addLine accepts discountPercent on new line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const r = addLine(invoice, { sku: 'ICON-SET', qty: 2, discountPercent: 15 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[1].discountPercent, 15);
});

test('addLine defaults discountPercent to 0', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const r = addLine(invoice, { sku: 'ICON-SET', qty: 2 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[1].discountPercent, 0);
});

test('addLine rejects invalid discountPercent', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  assert.deepEqual(addLine(invoice, { sku: 'ICON-SET', qty: 2, discountPercent: 101 }), { ok: false, error: 'DISCOUNT_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'ICON-SET', qty: 2, discountPercent: -1 }), { ok: false, error: 'DISCOUNT_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'ICON-SET', qty: 2, discountPercent: 'bad' }), { ok: false, error: 'DISCOUNT_INVALID' });
});

test('addLine updates discountPercent when adding to existing line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3, discountPercent: 10 }],
  }).value;
  const r = addLine(invoice, { sku: 'DES-HOUR', qty: 2, discountPercent: 20 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].discountPercent, 20);
});

test('invoiceTotals works with invoice from createInvoice with discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3, discountPercent: 10 },
      { sku: 'ICON-SET', qty: 2, discountPercent: 5 },
    ],
